#' Embed clonality assignments into a Seurat object (with optional sticky-ends rescue)
#'
#' Takes clonality tables generated by `tenx()` and embeds them into Seurat metadata.
#' When `sticky = TRUE`, single-chain cells may inherit the dominant paired clonotype
#' if their chain-specific CDR3 maps unambiguously to a paired clone (`dominant_purity`
#' above a chain-specific threshold).
#'
#' ## Chain-class purity asymmetry
#'
#' D-segment chains (IGH, TRB, TRD) have hyper-variable CDR3s that uniquely identify
#' a clone, so substring/exact CDR3 matches against the paired pool are typically pure
#' (purity = 1.0). Non-D chains (IGK, IGL, TRA, TRG) have constrained CDR3 length and
#' a limited V repertoire, so the same CDR3 typically appears across many unrelated
#' paired clones, producing low-purity, untrustworthy rescues.
#'
#' The default `purity` argument therefore encodes this asymmetry: D-gene chains rescue
#' at 0.9, non-D chains skip rescue entirely (`NA`). Users can override per-chain.
#'
#' ## Outputs
#'
#' On a sticky run the function adds these columns to the Seurat metadata:
#' - `Res_clonality` — the (possibly rescued) clonality ID
#' - `Res_clonality.correction` — `"Normal"`, `"Corrected"`, `"Not tested"`,
#'   `"Not tested (chain skipped)"`, `"Not tested (cdr3 too short)"`, or
#'   `"Not tested (no match)"`
#' - `Res_dominant_purity` — numeric in \[0, 1\] giving the dominant-paired-clone fraction
#'   among all paired pool rows that matched this single's CDR3, or `NA` if not tested.
#'   Useful for plotting (e.g. alluvial of single-clone → paired-clone with ribbon
#'   alpha proportional to purity).
#' - `Res_mapping_source` — which CDR3 column produced the match
#'
#' @param seu Seurat object to embed with clonality data.
#' @param clonal.list Character. Names of clonality objects to embed. Default: `ls(pattern = "^Clonal")`.
#' @param cdr3_map Character. Candidate CDR3 column names used to map single chains to
#'   paired chains. Default: `"cdr3_col2"` (amino-acid CDR3).
#' @param cell Character. `"B"`, `"T"`, or `"Tgd"`.
#' @param purity Named list / numeric. Per-chain minimum dominant-purity required for
#'   rescue. The default skips non-D chains:
#'   `list(IGH = 0.9, IGK = NA, IGL = NA, TRB = 0.9, TRA = NA, TRD = 0.9, TRG = NA)`.
#'   A scalar (e.g. `0.8`) is accepted for back-compat: it is expanded to all chains
#'   with a one-time message recommending the chain-aware defaults.
#' @param min_cdr3_aa Integer. Minimum CDR3 length (aa) for a single-chain cell to be
#'   considered for rescue. Cells with shorter CDR3s are reported as
#'   `"Not tested (cdr3 too short)"`. Default: `9`.
#' @param match_mode Character. `"exact"` (default) requires `pair_cdr3 == single_cdr3`;
#'   `"substring"` keeps the legacy `grepl(fixed = TRUE)` behavior, which is appropriate
#'   only for truncated-read pipelines.
#' @param require_v_gene Logical. If `TRUE` (default), additionally require the single
#'   and paired rows to share the same V gene at the matched chain. Skipped silently
#'   if no V-gene column can be resolved on either side.
#' @param sticky Logical. Run the rescue pass at all. Default: `FALSE`.
#' @param stick_only Character. `"all"` (default) or one of `TRA`, `TRB`, `TRD`, `TRG`,
#'   `IGH`, `IGK`, `IGL` to limit rescue to a single chain.
#' @param overwrite Logical. Overwrite any existing `Res_*` columns on the Seurat
#'   object. Default: `TRUE`.
#' @param verbose Logical. Print a per-chain rescue summary (via `inspect_purity()`)
#'   after the sticky pass. Default: `FALSE`.
#'
#' @return The Seurat object with `Res_*` columns added to its metadata.
#'
#' @importFrom stringr str_count
#' @export
add_seurat_metadata <- function(seu = NULL,
                                clonal.list = ls(pattern = "^Clonal", envir = .GlobalEnv),
                                cdr3_map = "cdr3_col2",
                                cell = "T",
                                purity = NULL,
                                min_cdr3_aa = 9,
                                match_mode = c("exact", "substring"),
                                require_v_gene = TRUE,
                                stick_only = "all",
                                sticky = FALSE,
                                overwrite = TRUE,
                                verbose = FALSE) {

  if (is.null(seu)) stop("Please add Seurat object to merge clonality.")

  if (!requireNamespace("Seurat", quietly = TRUE)) {
    stop("This function requires the 'Seurat' package. Install it first.", call. = FALSE)
  }

  match_mode <- match.arg(match_mode)
  cdr3_map <- unique(as.character(cdr3_map))

  # ── Resolve per-chain purity defaults ────────────────────────────────────
  default_purity <- list(
    IGH = 0.9, IGK = NA_real_, IGL = NA_real_,
    TRB = 0.9, TRA = NA_real_, TRD = 0.9, TRG = NA_real_
  )

  if (is.null(purity)) {
    purity <- default_purity
  } else if (is.numeric(purity) && length(purity) == 1L && is.null(names(purity))) {
    message(
      "add_seurat_metadata: 'purity' was passed as a scalar (", purity, "). ",
      "Expanding to all chains for back-compat. Consider the chain-aware default ",
      "(D-gene chains 0.9, non-D chains NA) -- pass purity = NULL to use it. ",
      "Non-D chains (IGK, IGL, TRA, TRG) typically produce low-purity rescues ",
      "and may fabricate clonal expansions when rescued indiscriminately."
    )
    purity <- as.list(stats::setNames(rep(purity, length(default_purity)), names(default_purity)))
  } else if (is.list(purity) || (is.numeric(purity) && !is.null(names(purity)))) {
    # Merge user list onto the defaults so missing chains keep sensible defaults.
    user_purity <- as.list(purity)
    purity <- utils::modifyList(default_purity, user_purity)
  } else {
    stop("'purity' must be NULL, a single numeric value, or a named list/numeric vector.",
         call. = FALSE)
  }

  # ── Internal helpers ─────────────────────────────────────────────────────
  bind_named_objects <- function(object_names) {
    if (length(object_names) == 0) {
      return(data.frame())
    }
    dplyr::bind_rows(
      mget(object_names, envir = .GlobalEnv, inherits = FALSE),
      .id = ".clonal_source"
    )
  }

  get_chain_name <- function(source_name) {
    source_name <- sub("^Clonal\\.output\\.10x", "", source_name)
    if (grepl("_", source_name)) {
      return(NA_character_)
    }
    source_name
  }

  get_column_aliases <- function(base_name, chain_name) {
    aliases <- base_name

    if (!is.na(chain_name) && nzchar(chain_name)) {
      aliases <- c(
        aliases,
        paste0(base_name, "_", chain_name)
      )

      if (base_name == "cdr3_col2") {
        aliases <- c(aliases, paste0("cdr3_", chain_name))
      }

      if (base_name %in% c("CDR3", "cdr3_nt")) {
        aliases <- c(aliases, paste0("cdr3_nt_", chain_name))
      }

      if (base_name %in% c("v_gene", "v_genes")) {
        aliases <- c(aliases,
                     paste0("v_gene_", chain_name),
                     paste0("v_genes_", chain_name))
      }
    }

    unique(aliases)
  }

  resolve_v_cols <- function(single_row, paired_df, chain_name) {
    candidates <- get_column_aliases("v_genes", chain_name)
    candidates <- c(candidates, get_column_aliases("v_gene", chain_name))
    candidates <- unique(candidates)
    list(
      single = intersect(candidates, names(single_row))[1],
      pair   = intersect(candidates, names(paired_df))[1]
    )
  }

  not_tested <- function(reason, purity_value = NA_real_) {
    list(
      clonality = NA_character_,
      correction = reason,
      mapping_source = NA_character_,
      dominant_purity = purity_value
    )
  }

  match_single_to_pairs <- function(single_row, paired_df, map_candidates) {
    if (nrow(paired_df) == 0) {
      return(not_tested("Not tested"))
    }

    chain_name <- get_chain_name(single_row[[".clonal_source"]])
    if (is.na(chain_name)) {
      return(not_tested("Not tested"))
    }

    chain_purity <- purity[[chain_name]]
    if (is.null(chain_purity) || is.na(chain_purity)) {
      return(not_tested("Not tested (chain skipped)"))
    }

    # V-gene resolution (used after CDR3 match if require_v_gene = TRUE)
    v_cols <- if (require_v_gene) resolve_v_cols(single_row, paired_df, chain_name) else NULL

    best_purity  <- NA_real_
    best_result  <- NULL

    for (map_name in map_candidates) {
      single_cols <- get_column_aliases(map_name, chain_name)
      pair_cols   <- get_column_aliases(map_name, chain_name)

      single_col <- intersect(single_cols, names(single_row))[1]
      pair_col   <- intersect(pair_cols, names(paired_df))[1]

      if (is.na(single_col) || is.na(pair_col)) {
        next
      }

      single_value <- as.character(single_row[[single_col]])
      if (is.na(single_value) || !nzchar(single_value)) {
        next
      }

      if (nchar(single_value) < min_cdr3_aa) {
        # Shorter than informative threshold; record reason if no other column rescues it.
        if (is.null(best_result)) {
          best_result <- not_tested("Not tested (cdr3 too short)")
        }
        next
      }

      pair_values <- as.character(paired_df[[pair_col]])

      if (match_mode == "exact") {
        match_idx <- !is.na(pair_values) & pair_values == single_value
      } else {
        match_idx <- !is.na(pair_values) & grepl(single_value, pair_values, fixed = TRUE)
      }

      matched <- paired_df[match_idx, , drop = FALSE]

      # V-gene additional filter
      if (require_v_gene && nrow(matched) > 0 &&
          !is.null(v_cols) && !is.na(v_cols$single) && !is.na(v_cols$pair)) {
        single_v <- as.character(single_row[[v_cols$single]])
        pair_v   <- as.character(matched[[v_cols$pair]])
        if (!is.na(single_v) && nzchar(single_v)) {
          matched <- matched[!is.na(pair_v) & pair_v == single_v, , drop = FALSE]
        }
      }

      if (nrow(matched) == 0) {
        next
      }

      tb <- table(matched[["clonality"]])
      dominant <- names(which.max(tb))[1]
      dominant_purity <- max(tb) / sum(tb)

      # Track the highest-purity match across map_candidates so we always report
      # the strongest piece of evidence we found.
      if (is.na(best_purity) || dominant_purity > best_purity) {
        best_purity <- dominant_purity
        if (dominant_purity >= chain_purity) {
          correction <- if (identical(as.character(single_row[["clonality"]]), dominant)) "Normal" else "Corrected"
          best_result <- list(
            clonality = dominant,
            correction = correction,
            mapping_source = map_name,
            dominant_purity = dominant_purity
          )
        } else {
          best_result <- list(
            clonality = NA_character_,
            correction = "Not tested",
            mapping_source = map_name,
            dominant_purity = dominant_purity
          )
        }
      }
    }

    if (is.null(best_result)) {
      return(not_tested("Not tested (no match)"))
    }

    best_result
  }

  # ── Identify singles, pairs, rest ────────────────────────────────────────
  singles <- clonal.list[!grepl("_", sub("^Clonal\\.output\\.10x", "", clonal.list))]

  if (!identical(stick_only, "all")) {
    singles <- singles[grepl(stick_only, singles)]
    if (length(singles) == 0) {
      stop(sprintf("No detected %s", stick_only))
    }
  }

  pair_match <- switch(
    cell,
    "B"   = c("Clonal.output.10xIGH_IGK", "Clonal.output.10xIGH_IGL"),
    "T"   = "Clonal.output.10xTRA_TRB",
    "Tgd" = "Clonal.output.10xTRD_TRG",
    stop("Unsupported cell type. Use 'B', 'T', or 'Tgd'.", call. = FALSE)
  )

  pairs <- clonal.list[clonal.list %in% pair_match]

  if (length(pairs) == 0) {
    stop(sprintf("No paired clonality objects detected for cell type '%s'.", cell), call. = FALSE)
  }

  rest <- setdiff(clonal.list, c(singles, pairs))

  c1 <- bind_named_objects(singles)
  c2 <- bind_named_objects(pairs)
  c3 <- bind_named_objects(rest)

  # ── Sticky-ends rescue pass ──────────────────────────────────────────────
  if (sticky && nrow(c1) > 0 && nrow(c2) > 0) {
    # One-shot session message about match-mode default
    if (match_mode == "exact" && !isTRUE(getOption("clonality.exact_msg_shown", FALSE))) {
      message(
        "add_seurat_metadata: match_mode = 'exact' is the default in v0.11+. ",
        "Pass match_mode = 'substring' to recover the legacy behavior (recommended ",
        "only for truncated-read pipelines)."
      )
      options(clonality.exact_msg_shown = TRUE)
    }

    mapped <- lapply(seq_len(nrow(c1)), function(i) {
      match_single_to_pairs(
        single_row = c1[i, , drop = FALSE],
        paired_df = c2,
        map_candidates = cdr3_map
      )
    })

    c1$clonality.corrected   <- vapply(mapped, `[[`, character(1), "clonality")
    c1$clonality.correction  <- vapply(mapped, `[[`, character(1), "correction")
    c1$mapping_source        <- vapply(mapped, `[[`, character(1), "mapping_source")
    c1$dominant_purity       <- vapply(mapped, `[[`, numeric(1), "dominant_purity")
    c1$clonality             <- dplyr::coalesce(c1$clonality.corrected, c1$clonality)
    c1$clonality.corrected   <- NULL
  }

  if (sticky && nrow(c1) > 0) {
    if (!"clonality.correction" %in% names(c1)) c1$clonality.correction <- "Not tested"
    if (!"mapping_source"       %in% names(c1)) c1$mapping_source       <- NA_character_
    if (!"dominant_purity"      %in% names(c1)) c1$dominant_purity      <- NA_real_
  }

  # Keep ONE row per barcode if the caller's clonal pools overlap (e.g. both light classes are
  # present, so a heavy-only cell can map into an IGH_IGK *and* an IGH_IGL clone): prefer the paired
  # assignment, then multi-chain, then single -- never emit a duplicate barcode (the sticky rescue's
  # `purity` guard already resolves which single pair a heavy-only cell joins).
  if (nrow(c1)) c1$.sticky_prio <- 3L
  if (nrow(c2)) c2$.sticky_prio <- 1L
  if (nrow(c3)) c3$.sticky_prio <- 2L
  c0 <- dplyr::bind_rows(c1, c2, c3)
  if ("barcodes" %in% names(c0) && any(duplicated(c0[["barcodes"]]))) {
    c0 <- c0[order(c0$.sticky_prio), , drop = FALSE]
    c0 <- c0[!duplicated(c0[["barcodes"]]), , drop = FALSE]
  }
  c0$.sticky_prio <- NULL

  if (".clonal_source" %in% names(c0)) {
    c0$.clonal_source <- NULL
  }

  c0 <- as.data.frame(c0)
  colnames(c0) <- paste0("Res_", colnames(c0))

  if ("Res_barcodes" %in% colnames(c0)) {
    rownames(c0) <- c0[["Res_barcodes"]]
  }

  if (sticky && "Res_clonality.correction" %in% colnames(c0)) {
    c0$Res_clonality.correction[is.na(c0$Res_clonality.correction)] <- "Not tested"
  }

  if (overwrite) {
    seu@meta.data <- seu@meta.data %>% dplyr::select(-dplyr::contains("Res_"))
  }

  seu <- Seurat::AddMetaData(seu, metadata = c0)

  if (verbose && sticky) {
    try(inspect_purity(seu), silent = TRUE)
  }

  return(seu)
}
